 			ret += hh * usPerHr;
 			ret += mm * usPerMin;
 			ret += ss * usPerSec;
 			ret += us;
-			return ret;
+			return ret * 1e-6;
 		}

 		throw new InputErrorException(INP_ERR_BADDATE, input);
 	}



